//	--------------------------------------------------------------------------------
int CvPlayer::GetDiplomaticPrestige() const
{
	int iResult = GetCurrentEra() + GetExtraDiplomaticPrestige();

#if defined(MOD_SP_UNIQUE_CITYSTATE)
	CvPlayerCityStateUA* pUA = GetPlayerCityStateUA();
	if (pUA)
	{
		int iPerCity = pUA->GetDiplomaticPrestigePerCity();
		if (iPerCity > 0)
			iResult += (getNumCities() * iPerCity) / 100;

		// Geneva CS UA: "World Recognition" - +1 diplomatic prestige per 2 major civilizations
		// whose majority religion is the religion the ally leads (counting the ally itself).
		int iPerMajorityCiv = pUA->GetDiplomaticPrestigePerMajorityCiv();
		if (iPerMajorityCiv > 0)
		{
			ReligionTypes eMyReligion = GetReligions()->GetReligionCreatedByPlayer();
			if (eMyReligion != NO_RELIGION)
			{
				int iCount = 0;
				for (int j = 0; j < MAX_MAJOR_CIVS; j++)
				{
					CvPlayer& kCiv = GET_PLAYER((PlayerTypes)j);
					if (kCiv.isAlive() && !kCiv.isMinorCiv() && kCiv.GetReligions()->HasReligionInMostCities(eMyReligion))
						iCount++;
				}
				iResult += (iCount * iPerMajorityCiv) / 100;
			}
		}
	}
#endif

	//Master Spy diplomat: every Master Spy we keep stationed abroad as a diplomat is worth +1 prestige.
	//Computed on the fly so it tracks the diplomat's presence immediately, with no stored state.
	//City-states have no spies and must not walk the per-major espionage arrays.
	CvPlayerEspionage* pMasterSpyEspionage = GetEspionage();
	if (!isMinorCiv() && pMasterSpyEspionage != NULL)
	{
		for (int iLoop = 0; iLoop < MAX_MAJOR_CIVS; iLoop++)
		{
			PlayerTypes eLoopMajor = (PlayerTypes) iLoop;
			if (eLoopMajor == GetID())
				continue;

			if (GET_PLAYER(eLoopMajor).isAlive() && pMasterSpyEspionage->HasMasterSpyDiplomatVisitingThem(eLoopMajor))
			{
				iResult += 1;
			}
		}
	}

	return iResult;
}

